template.content:
/* Quick setup example for HTTP Server.
*/

void lwip_http_server_quick_setup(void);

/* Quick setup for HTTP Server. */
void lwip_http_server_quick_setup(void)
{
    /* Initialize the lwIP HTTP Server */
    httpd_init();

    /* Waiting for connection to be established. */
    while (true)
    {
        #if NO_SYS
            R_BSP_SoftwareDelay(1, BSP_DELAY_UNITS_MILLISECONDS);
            sys_check_timeouts();
        #else
            sys_msleep(1);
        #endif
    }
}
